use std::fmt::Display;

fn largest<T>(items: &[T]) -> &T {
    let mut best = &items[0];
    for item in items {
        if item > best {
            best = item;
        }
    }
    best
}

fn banner<T>(value: T) -> String {
    format!("** {} **", value.to_string().to_uppercase())
}

fn announce<T>(label: &str, value: T) {
    println!("{label}: {value}");
}

fn main() {
    let cannons = [3, 9, 4];
    let ships = ["brig", "sloop", "galleon"];
    announce("most cannons", largest(&cannons));
    announce("last by name", largest(&ships));
    println!("{}", banner(largest(&ships)));
    println!("{}", banner(7));
}

