use std::cmp::Ordering;
use std::fmt;

#[derive(Debug, PartialEq, Eq)]
struct Cargo {
    name: String,
    weight: u32,
}

impl fmt::Display for Cargo {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{} ({} kg)", self.name, self.weight)
    }
}

impl Default for Cargo {
    fn default() -> Self {
        Cargo {
            name: String::from("ballast"),
            weight: 0,
        }
    }
}

impl From<(&str, u32)> for Cargo {
    fn from(pair: (&str, u32)) -> Self {
        let (name, weight) = pair;
        Cargo {
            name: name.to_string(),
            weight,
        }
    }
}

impl Ord for Cargo {
    fn cmp(&self, other: &Self) -> Ordering {
        self.weight
            .cmp(&other.weight)
            .then_with(|| self.name.cmp(&other.name))
    }
}

impl PartialOrd for Cargo {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let mut hold: Vec<Cargo> = vec![
        ("rum", 40).into(),
        Cargo::from(("silk", 15)),
        Cargo::default(),
    ];
    hold.sort();
    for crate_ in &hold {
        println!("{crate_}");
    }
    if let Some(heaviest) = hold.iter().max() {
        println!("heaviest: {heaviest}");
    }
}

