/// Yields 1, 2, 4, 8, ... while the value is at most `limit`.
struct Doubling {
    next: u32,
    limit: u32,
}

impl Doubling {
    fn up_to(limit: u32) -> Self {
        Doubling { next: 1, limit }
    }
}

impl Iterator for Doubling {
    type Item = u32;

    fn next(&mut self) -> Option<u32> {
        if self.next > self.limit {
            return None;
        }
        let current = self.next;
        self.next *= 2;
        Some(current)
    }
}

fn hoard(limit: u32) -> u32 {
    Doubling::up_to(limit).sum()
}

fn first_nights(limit: u32, n: usize) -> Vec<u32> {
    Doubling::up_to(limit).take(n).collect()
}

fn count_at_least(limit: u32, min: u32) -> usize {
    Doubling::up_to(limit).filter(|&v| v >= min).count()
}

fn main() {
    println!("hoard up to 100: {}", hoard(100));
    println!("first 3 nights: {:?}", first_nights(100, 3));
    println!("piles of 10 or more: {}", count_at_least(100, 10));
}

