trait Crewmate {
    fn name(&self) -> &str;

    /// Percent of the chest.
    fn share(&self) -> u32;

    fn payout(&self, chest: u32) -> u32 {
        chest * self.share() / 100
    }

    fn greeting(&self) -> String {
        format!("Aye, I'm {}", self.name())
    }
}

struct Captain {
    name: String,
}

struct Deckhand {
    name: String,
    years: u32,
}

impl Crewmate for Captain {
    fn name(&self) -> &str {
        &self.name
    }

    fn share(&self) -> u32 {
        20
    }

    fn greeting(&self) -> String {
        format!("Captain {}, at your service", self.name)
    }
}

impl Crewmate for Deckhand {
    fn name(&self) -> &str {
        &self.name
    }

    fn share(&self) -> u32 {
        (2 + self.years).min(10)
    }
}

fn total_payout(crew: &[Box<dyn Crewmate>], chest: u32) -> u32 {
    crew.iter().map(|member| member.payout(chest)).sum()
}

fn introduce(member: &impl Crewmate) -> String {
    format!("{} ({}%)", member.greeting(), member.share())
}

fn main() {
    let flint = Captain {
        name: String::from("Flint"),
    };
    println!("{}", introduce(&flint));
    let crew: Vec<Box<dyn Crewmate>> = vec![
        Box::new(flint),
        Box::new(Deckhand {
            name: String::from("Ann"),
            years: 3,
        }),
    ];
    println!("payout of 1000: {}", total_payout(&crew, 1000));
}

