use std::fmt;
use std::io::{self, Read};

trait Ship {
    fn name(&self) -> &str;
    fn speed(&self) -> u32;
    fn describe(&self) -> String {
        format!("{} sails at {} knots", self.name(), self.speed())
    }
}

struct Sloop {
    name: String,
    knots: u32,
}

struct Galleon {
    name: String,
    guns: u32,
}

struct Raft {
    name: String,
}

impl Ship for Sloop {
    fn name(&self) -> &str {
        &self.name
    }
    fn speed(&self) -> u32 {
        self.knots
    }
}

impl Ship for Galleon {
    fn name(&self) -> &str {
        &self.name
    }
    fn speed(&self) -> u32 {
        6
    }
    fn describe(&self) -> String {
        format!("{} sails at 6 knots with {} guns", self.name, self.guns)
    }
}

impl Ship for Raft {
    fn name(&self) -> &str {
        &self.name
    }
    fn speed(&self) -> u32 {
        2
    }
}

/// Parses one log line. Unknown or malformed lines give None.
fn parse_ship(line: &str) -> Option<Box<dyn Ship>> {
    let words: Vec<&str> = line.split_whitespace().collect();
    match words.as_slice() {
        ["sloop", name, knots] => Some(Box::new(Sloop {
            name: name.to_string(),
            knots: knots.parse().ok()?,
        })),
        ["galleon", name, guns] => Some(Box::new(Galleon {
            name: name.to_string(),
            guns: guns.parse().ok()?,
        })),
        ["raft", name] => Some(Box::new(Raft {
            name: name.to_string(),
        })),
        _ => None,
    }
}

struct Fleet {
    ships: Vec<Box<dyn Ship>>,
}

impl Fleet {
    /// The speed of the slowest ship, or 0 for an empty fleet.
    fn speed(&self) -> u32 {
        self.ships.iter().map(|s| s.speed()).min().unwrap_or(0)
    }
}

impl fmt::Display for Fleet {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        writeln!(
            f,
            "Fleet of {}, speed {} knots",
            self.ships.len(),
            self.speed()
        )?;
        for ship in &self.ships {
            writeln!(f, "- {}", ship.describe())?;
        }
        Ok(())
    }
}

fn main() {
    let mut log = String::new();
    io::stdin().read_to_string(&mut log).unwrap();
    let mut ships = Vec::new();
    for line in log.lines() {
        if let Some(ship) = parse_ship(line) {
            ships.push(ship);
        }
    }
    ships.sort_by(|a, b| {
        b.speed()
            .cmp(&a.speed())
            .then_with(|| a.name().cmp(b.name()))
    });
    let fleet = Fleet { ships };
    print!("{fleet}");
}
